sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float grainSize;
uniform float roughness;
uniform float response;
uniform float chroma;
uniform float animated;
uniform float fps;
uniform float seed;
uniform float blend;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float t = animated > 0.5 ? floor(time * fps) : 0.0;
    float2 p = coord / max(grainSize, 0.5) + seed * 13.7 + t * 17.0;
    float n = (hash21(p) + hash21(p + 3.7) + hash21(p + 9.1)) / 3.0 - 0.5;
    n = mix(n, vnoise(p * 0.5) - 0.5, roughness);
    float3 cn = float3(hash21(p + 1.3), hash21(p + 5.9), hash21(p + 8.2)) - 0.5;
    float l = luma(s);
    float resp = mix(1.0, 4.0 * l * (1.0 - l), response);
    float3 layer = saturate(0.5 + (float3(n) + cn * chroma) * amount * resp * 2.0);
    float3 o = blendm(s, layer, blend);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
